import React, { useEffect, useState } from 'react'
import { Link } from 'react-router-dom'
import SectionTitleComponent from '../components/SectionTitleComponent'
import ProgramStudiCardComponent from '../components/ProgramStudiCardComponent'
import ProgramStudiData from '../data/ProgramStudiData'
import { supabase } from '../lib/supabaseClient'

export default function HomePage() {
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState(null)
  const [slides, setSlides] = useState([])
  const [mitra, setMitra] = useState([])
  const [biaya, setBiaya] = useState([])
  const [testimoni, setTestimoni] = useState([])
  
  // Edit states
  const [editingSlide, setEditingSlide] = useState(null)
  const [editingMitra, setEditingMitra] = useState(null)
  const [editingBiaya, setEditingBiaya] = useState(null)
  const [editingTestimoni, setEditingTestimoni] = useState(null)

  useEffect(() => {
    let mounted = true

    async function load() {
      setLoading(true)
      setError(null)
      try {
        const [s1, s2, s3, s4] = await Promise.all([
          supabase.from('slideshow').select('*').order('order_index', { ascending: true }),
          supabase.from('mitra').select('*').order('created_at', { ascending: true }),
          supabase.from('biaya_kuliah').select('*').order('prodi_name', { ascending: true }),
          supabase.from('testimoni').select('*').order('created_at', { ascending: false }),
        ])

        if (!mounted) return

        if (s1.error || s2.error || s3.error || s4.error) {
          setError(s1.error || s2.error || s3.error || s4.error)
        } else {
          setSlides(s1.data || [])
          setMitra(s2.data || [])
          setBiaya(s3.data || [])
          setTestimoni(s4.data || [])
        }
      } catch (err) {
        setError(err)
      } finally {
        setLoading(false)
      }
    }

    load()
    return () => {
      mounted = false
    }
  }, [])

  // CRUD Functions
  async function handleDeleteSlide(id) {
    if (!confirm('Hapus slide ini?')) return
    const { error } = await supabase.from('slideshow').delete().eq('id', id)
    if (error) setError(error)
    else {
      setSlides(slides.filter(s => s.id !== id))
    }
  }

  async function handleDeleteMitra(id) {
    if (!confirm('Hapus mitra ini?')) return
    const { error } = await supabase.from('mitra').delete().eq('id', id)
    if (error) setError(error)
    else {
      setMitra(mitra.filter(m => m.id !== id))
    }
  }

  async function handleDeleteBiaya(id) {
    if (!confirm('Hapus biaya ini?')) return
    const { error } = await supabase.from('biaya_kuliah').delete().eq('id', id)
    if (error) setError(error)
    else {
      setBiaya(biaya.filter(b => b.id !== id))
    }
  }

  async function handleDeleteTestimoni(id) {
    if (!confirm('Hapus testimoni ini?')) return
    const { error } = await supabase.from('testimoni').delete().eq('id', id)
    if (error) setError(error)
    else {
      setTestimoni(testimoni.filter(t => t.id !== id))
    }
  }

  return (
    <div className="space-y-16 py-10">
      <section className="rounded-[2rem] bg-green-600/10 p-6 md:p-14 shadow-lg">
        <div className="max-w-4xl mx-auto text-center">
          <p className="text-sm uppercase tracking-[0.3em] text-green-600 font-semibold mb-4">Selamat datang</p>
          <h1 className="text-4xl md:text-5xl font-extrabold text-gray-900 mb-6">Politeknik Caltex Riau</h1>
          <p className="text-gray-600 text-lg md:text-xl max-w-3xl mx-auto mb-8">
            Temukan program studi unggulan kami dan mulai perjalanan kariermu di dunia teknologi, industri, dan ilmu terapan.
          </p>
          <Link
            to="/prodi"
            className="inline-flex items-center justify-center rounded-full bg-green-600 px-8 py-3 text-white font-semibold shadow-lg hover:bg-green-700 transition"
          >
            Lihat Program Studi
          </Link>
        </div>
      </section>

      <section>
        <div className="flex items-center justify-between mb-4">
          <SectionTitleComponent title="Slideshow" subtitle="Highlight" />
          <Link
            to="/admin"
            className="px-4 py-2 bg-green-600 text-white rounded hover:bg-green-700 text-sm"
          >
            + Tambah Slide
          </Link>
        </div>
        {loading ? (
          <p>Loading slideshow...</p>
        ) : error ? (
          <p className="text-red-600">Error: {error.message || String(error)}</p>
        ) : (
          <div className="space-y-4">
            <div className="grid gap-4 sm:grid-cols-2">
              {slides.map((s) => {
                const fallback = `https://via.placeholder.com/1200x500?text=${encodeURIComponent(s.title || 'Slide')}`
                return (
                  <div key={s.id} className="rounded-lg overflow-hidden shadow bg-white group relative">
                    {s.image_url ? (
                      <img
                        src={s.image_url}
                        alt={s.title}
                        loading="lazy"
                        className="w-full h-48 object-cover bg-gray-100"
                        onError={(e) => {
                          e.currentTarget.onerror = null
                          e.currentTarget.src = fallback
                        }}
                      />
                    ) : (
                      <img src={fallback} alt={s.title} className="w-full h-48 object-cover" />
                    )}
                    <div className="p-4">
                      <h3 className="font-semibold text-lg">{s.title}</h3>
                      <p className="text-sm text-gray-600">{s.subtitle}</p>
                      <div className="flex gap-2 mt-3">
                        <Link
                          to="/admin"
                          className="flex-1 px-2 py-1 bg-blue-500 text-white text-xs rounded hover:bg-blue-600 text-center"
                        >
                          Edit
                        </Link>
                        <button
                          onClick={() => handleDeleteSlide(s.id)}
                          className="flex-1 px-2 py-1 bg-red-500 text-white text-xs rounded hover:bg-red-600"
                        >
                          Hapus
                        </button>
                      </div>
                    </div>
                  </div>
                )
              })}
            </div>
          </div>
        )}
      </section>

      <section>
        <div className="flex items-center justify-between mb-4">
          <SectionTitleComponent title="Mitra" subtitle="Kolaborator kami" />
          <Link
            to="/admin"
            className="px-4 py-2 bg-green-600 text-white rounded hover:bg-green-700 text-sm"
          >
            + Tambah Mitra
          </Link>
        </div>
        {loading ? (
          <p>Loading mitra...</p>
        ) : (
          <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6">
            {mitra.map((m) => (
              <div
                key={m.id}
                className="flex flex-col items-center gap-3 p-4 bg-white rounded-lg shadow hover:shadow-lg transform hover:-translate-y-1 transition-all duration-200"
              >
                <div className="w-full h-20 flex items-center justify-center bg-gray-50 rounded-md overflow-hidden">
                  <img
                    src={m.logo_url || `https://via.placeholder.com/200x80?text=${encodeURIComponent(m.name || 'Mitra')}`}
                    alt={m.name}
                    className="max-h-16 object-contain"
                    onError={(e) => {
                      e.currentTarget.onerror = null
                      e.currentTarget.src = `https://via.placeholder.com/200x80?text=${encodeURIComponent(m.name || 'Mitra')}`
                    }}
                  />
                </div>
                <div className="text-center">
                  <div className="font-semibold text-sm text-gray-800">{m.name}</div>
                </div>
                <div className="flex gap-2 w-full">
                  <Link
                    to="/admin"
                    className="flex-1 px-2 py-1 bg-blue-500 text-white text-xs rounded hover:bg-blue-600 text-center"
                  >
                    Edit
                  </Link>
                  <button
                    onClick={() => handleDeleteMitra(m.id)}
                    className="flex-1 px-2 py-1 bg-red-500 text-white text-xs rounded hover:bg-red-600"
                  >
                    Hapus
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </section>

      <section>
        <div className="flex items-center justify-between mb-4">
          <SectionTitleComponent title="Biaya Kuliah" subtitle="Per prodi" />
          <Link
            to="/admin"
            className="px-4 py-2 bg-green-600 text-white rounded hover:bg-green-700 text-sm"
          >
            + Tambah Biaya
          </Link>
        </div>
        {loading ? (
          <p>Loading biaya...</p>
        ) : (
          <div className="grid gap-6 sm:grid-cols-2 xl:grid-cols-3">
            {biaya.map((b) => (
              <div key={b.id} className="p-4 bg-white rounded shadow">
                <h4 className="font-semibold">{b.prodi_name}</h4>
                <p className="text-sm text-gray-600">{b.gelombang}</p>
                <p className="mt-2 font-bold">Rp {Number(b.nominal).toLocaleString('id-ID')}</p>
                {b.keterangan && <p className="text-sm text-gray-500">{b.keterangan}</p>}
                <div className="flex gap-2 mt-3">
                  <Link
                    to="/admin"
                    className="flex-1 px-2 py-1 bg-blue-500 text-white text-xs rounded hover:bg-blue-600 text-center"
                  >
                    Edit
                  </Link>
                  <button
                    onClick={() => handleDeleteBiaya(b.id)}
                    className="flex-1 px-2 py-1 bg-red-500 text-white text-xs rounded hover:bg-red-600"
                  >
                    Hapus
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </section>

      <section>
        <div className="flex items-center justify-between mb-4">
          <SectionTitleComponent title="Testimoni" subtitle="Apa kata mereka" />
          <Link
            to="/admin"
            className="px-4 py-2 bg-green-600 text-white rounded hover:bg-green-700 text-sm"
          >
            + Tambah Testimoni
          </Link>
        </div>
        {loading ? (
          <p>Loading testimoni...</p>
        ) : (
          <div className="grid gap-6 sm:grid-cols-2">
            {testimoni.map((t) => (
              <div key={t.id} className="p-4 bg-white rounded shadow">
                <div className="flex items-center gap-4">
                  <img src={t.avatar_url} alt={t.name} className="w-12 h-12 rounded-full object-cover" />
                  <div>
                    <div className="font-semibold">{t.name}</div>
                    <div className="text-sm text-gray-500">{t.role} — {t.rating} ⭐</div>
                  </div>
                </div>
                <p className="mt-3 text-gray-700">{t.content}</p>
                <div className="flex gap-2 mt-3">
                  <Link
                    to="/admin"
                    className="flex-1 px-2 py-1 bg-blue-500 text-white text-xs rounded hover:bg-blue-600 text-center"
                  >
                    Edit
                  </Link>
                  <button
                    onClick={() => handleDeleteTestimoni(t.id)}
                    className="flex-1 px-2 py-1 bg-red-500 text-white text-xs rounded hover:bg-red-600"
                  >
                    Hapus
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </section>

      <section>
        <SectionTitleComponent title="Program Studi" subtitle="Pilihan Prodi" />
        <div className="grid gap-6 sm:grid-cols-2 xl:grid-cols-3">
          {ProgramStudiData.map((prodi) => (
            <ProgramStudiCardComponent
              key={prodi.id}
              nama={prodi.nama}
              deskripsi={prodi.deskripsi}
            />
          ))}
        </div>
      </section>
    </div>
  )
}
